def read(p):return json.loads(Path(p).read_text())
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def require(x,m):
 if not x:raise RuntimeError(m)
def write(name,value):
 with(HERE/name).open('x')as f:json.dump(value,f,ensure_ascii=False,sort_keys=True,indent=2,allow_nan=False);f.write('\n')
def main():
 obs=read(HERE/'RESOURCE_TERMINAL_OBSERVATIONS.json');src=ROOT/'staging/payload_v1/gpu0/qualification/resource_event_reducer.py';raw=src.read_bytes()
 with(HERE/'FROZEN_RESOURCE_EVENT_REDUCER.py').open('xb')as f:f.write(raw)
 ns={};exec(compile(raw,str(src),'exec'),ns);reducer=ns['reduce_events'];old=read(ROOT/'analysis/REPAIR_PROVENANCE.json');checks={};cards=[];lower=upper=0.;n_dispatch=n_exit=n_release=n_pass=n_abort=n_fail=0
 require(obs['shared']['FIRST_FAILURE.json']['json']['status']=='FAIL_CLOSED_STOP'and obs['shared']['SESSION_RESULT.json']['json']['status']=='FAIL_CLOSED_STOP','No actual global STOP')
 for n in range(4):
  key='gpu'+str(n);v=obs['cards'][key];auth=read(ROOT/'staging/payload_v1'/key/'AUTHORIZATION.json');require(v['reducer_source']['sha256']==sha(src)and v['reducer_source']['raw'].encode()==raw,'Remote frozen reducer changed')
  manifest=read(ROOT/'staging/payload_v1'/key/'SOURCE_MANIFEST.json');binding=next(x for x in manifest['execution_sources']if x['path']=='qualification/resource_event_reducer.py');require(binding['sha256']==sha(src),'Reducer manifest mismatch')
  es=v['events'];require(hashlib.sha256(es['raw'].encode()).hexdigest()==es['sha256'],'Event source hash changed');events=[json.loads(x)for x in es['raw'].splitlines()if x.strip()];red=reducer(events);ledger=v['metadata']['RESOURCE_LEDGER.json']['json'];require(not red['has_incomplete_units']and ledger['reduced_units']==red['units'],'Terminal ledger event replay mismatch:'+key)
  require(ledger['GPU_dispatches']==3 and ledger['observed_dispatch_reservation_GPUh_lower']==sum(x['occupied_seconds_lower']for x in red['units'])/3600 and ledger['observed_dispatch_reservation_GPUh_upper']==red['GPU_seconds_upper_bound']/3600,'Terminal ledger totals mismatch')
  grouped=collections.defaultdict(list)
